function tankStatus(value) {
  const text = String(value).trim();
  const n = Number(text);
  if (text === "" || Number.isNaN(n) || n < 0 || n > 100) return "Enter a level from 0 to 100";
  if (n < 20) return `Tank low: ${n}%`;
  if (n >= 90) return `Tank full: ${n}%`;
  return `Tank at ${n}%`;
}

const form = document.getElementById("reading-form");
form.addEventListener("submit", (event) => {
  event.preventDefault();   // stay on this page
  const level = document.getElementById("level");
  document.getElementById("status").textContent = tankStatus(level.value);
});
